"""Add synchronized document metadata and ordered parsed pages."""
from alembic import op

revision = '0011_proc_documents'
down_revision = '0010_proc_exceptions'
branch_labels = None
depends_on = None

SQL = "-- Metadata and parsed text only. Uploaded file bytes remain in existing private storage.\nCREATE TABLE public.proc_documents (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK(source_revision>=1),\n    filename text NOT NULL CHECK(length(filename)>0),\n    sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'),\n    status text NOT NULL CHECK(status IN ('review_required','quarantined')),\n    error text,\n    supplier_id varchar(64),\n    parser text NOT NULL CHECK(length(parser)>0),\n    malware_scanned boolean NOT NULL,\n    page_count integer NOT NULL CHECK(page_count BETWEEN 0 AND 60),\n    source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object'),\n    PRIMARY KEY(tenant,id),\n    FOREIGN KEY(tenant,id) REFERENCES public.records(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    FOREIGN KEY(tenant,supplier_id) REFERENCES public.proc_suppliers(tenant,id) DEFERRABLE INITIALLY DEFERRED\n);\nCREATE TABLE public.proc_document_pages (\n    tenant varchar(64) NOT NULL,\n    document_id varchar(64) NOT NULL,\n    page_index integer NOT NULL CHECK(page_index BETWEEN 0 AND 59),\n    text_content text NOT NULL CHECK(length(text_content)<=200000),\n    PRIMARY KEY(tenant,document_id,page_index),\n    FOREIGN KEY(tenant,document_id) REFERENCES public.proc_documents(tenant,id) DEFERRABLE INITIALLY DEFERRED\n);\nCREATE INDEX ix_proc_documents_supplier_status ON public.proc_documents(tenant,supplier_id,status);\nDO $$ DECLARE t text;\nBEGIN\n    FOREACH t IN ARRAY ARRAY['proc_documents','proc_document_pages'] LOOP\n        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);\n        EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);\n        EXECUTE format('CREATE POLICY tenant_scope ON public.%I TO supplypilot_app USING(tenant=NULLIF(current_setting(''supplypilot.tenant'',true),'''')) WITH CHECK(tenant=NULLIF(current_setting(''supplypilot.tenant'',true),''''))',t);\n        EXECUTE format('CREATE POLICY migration_owner ON public.%I TO supplypilot_migrator USING(true) WITH CHECK(true)',t);\n        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,supplypilot_app',t);\n        EXECUTE format('GRANT SELECT ON TABLE public.%I TO supplypilot_app',t);\n    END LOOP;\nEND $$;\n\nCREATE FUNCTION public.sync_procurement_document()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp\nAS $$ DECLARE d jsonb; key text;\nBEGIN\n    IF TG_OP='UPDATE' AND (OLD.kind='document' OR NEW.kind='document') AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Document identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='DELETE' THEN\n        IF OLD.kind='document' THEN\n            DELETE FROM public.proc_document_pages WHERE tenant=OLD.tenant AND document_id=OLD.id;\n            DELETE FROM public.proc_documents WHERE tenant=OLD.tenant AND id=OLD.id;\n        END IF;\n        RETURN OLD;\n    END IF;\n    IF NEW.kind<>'document' THEN RETURN NEW; END IF;\n    d:=NEW.data::jsonb;\n    FOREACH key IN ARRAY ARRAY['filename','sha256','status','parser'] LOOP\n        IF jsonb_typeof(d->key) IS DISTINCT FROM 'string' THEN\n            RAISE EXCEPTION 'Document metadata fields must be strings' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    FOREACH key IN ARRAY ARRAY['supplier_id','error'] LOOP\n        IF d ? key AND d->key<>'null'::jsonb AND jsonb_typeof(d->key)<>'string' THEN\n            RAISE EXCEPTION 'Optional document metadata must be string or null' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    IF jsonb_typeof(d->'malware_scanned') IS DISTINCT FROM 'boolean' OR\n       jsonb_typeof(d->'pages') IS DISTINCT FROM 'array' THEN\n        RAISE EXCEPTION 'Document requires scan flag and parsed page array' USING ERRCODE='23514';\n    END IF;\n    IF EXISTS(SELECT 1 FROM jsonb_array_elements(d->'pages') AS p(value) WHERE jsonb_typeof(p.value)<>'string') THEN\n        RAISE EXCEPTION 'Document pages must contain text strings' USING ERRCODE='23514';\n    END IF;\n    IF d->>'status'='review_required' AND NOT EXISTS(\n        SELECT 1 FROM jsonb_array_elements_text(d->'pages') AS p(value) WHERE p.value ~ '[^[:space:]]') THEN\n        RAISE EXCEPTION 'Reviewable document requires nonblank parsed text' USING ERRCODE='23514';\n    END IF;\n    INSERT INTO public.proc_documents VALUES(NEW.tenant,NEW.id,NEW.revision,d->>'filename',\n        d->>'sha256',d->>'status',d->>'error',d->>'supplier_id',d->>'parser',\n        (d->>'malware_scanned')::boolean,jsonb_array_length(d->'pages'),d-'pages')\n    ON CONFLICT(tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n        filename=EXCLUDED.filename,sha256=EXCLUDED.sha256,status=EXCLUDED.status,error=EXCLUDED.error,\n        supplier_id=EXCLUDED.supplier_id,parser=EXCLUDED.parser,malware_scanned=EXCLUDED.malware_scanned,\n        page_count=EXCLUDED.page_count,source_snapshot=EXCLUDED.source_snapshot;\n    DELETE FROM public.proc_document_pages WHERE tenant=NEW.tenant AND document_id=NEW.id;\n    INSERT INTO public.proc_document_pages\n    SELECT NEW.tenant,NEW.id,(p.ordinality-1)::integer,p.value\n    FROM jsonb_array_elements_text(d->'pages') WITH ORDINALITY AS p(value,ordinality);\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_document() FROM PUBLIC,supplypilot_app;\nCREATE TRIGGER records_document_sync AFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_document();\nUPDATE public.records SET data=data WHERE kind='document';\n"


def upgrade():
    op.execute(SQL)


def downgrade():
    raise RuntimeError('Restore a reviewed backup; automatic document projection removal is disabled.')
